template <int N>
struct Factorial {
    // Compiler recurses here until N=0
    static constexpr int value = N * Factorial<N - 1>::value;
};

// Specialization: Termination condition (Base Case)
template <>
struct Factorial<0> {
    static constexpr int value = 1;
};

// Result is computed entirely at compile time
// Compiler generated Factorial<5>, Factorial<4>, ... Factorial<0>
static constexpr int result_5 = Factorial<5>::value; // 120

// Avoids runtime stack overhead and computation
struct CompileTimeCheck {
    static_assert(Factorial<7>::value == 5040);
};
